 static readonly Color Ink=new Color(.055f,.065f,.067f),Wood=new Color(.36f,.25f,.15f),Leaf=new Color(.16f,.24f,.12f),Rust=new Color(.45f,.26f,.16f),Cloth=new Color(.30f,.37f,.32f),Steel=new Color(.24f,.29f,.29f);
 Mesh leafMesh,grassMesh;Theme comicTheme;Label zoneLabel,clockLabel,hpLabel,needsLabel,ammoLabel,woundLabel,promptLabel,helpLabel;ProgressBar hpBar,staminaBar;Control hudRoot;ColorRect damageTint;double artHitFlash;
 MeshInstance3D Ellipsoid(Node3D parent,Vector3 pos,Vector3 radius,Color color){var m=new MeshInstance3D{Mesh=new SphereMesh{Radius=1,Height=2,RadialSegments=12,Rings=6},Scale=radius,Position=pos,MaterialOverride=Material(color)};parent.AddChild(m);return m;}
 MeshInstance3D Tube(Node3D parent,Vector3 a,Vector3 b,float radius,Color color,float tip=-1){var delta=b-a;var m=new MeshInstance3D{Mesh=new CylinderMesh{TopRadius=tip<0?radius:tip,BottomRadius=radius,Height=delta.Length(),RadialSegments=10},Position=(a+b)*.5f,MaterialOverride=Material(color)};parent.AddChild(m);m.Quaternion=new Quaternion(Vector3.Up,delta.Normalized());return m;}
 Mesh BevelMesh(Vector3 size){float x=size.X*.5f,y=size.Y*.5f,z=size.Z*.5f,c=Math.Min(x,y)*.28f;Vector2[] ring={new(-x+c,y),new(x-c,y),new(x,y-c),new(x,-y+c),new(x-c,-y),new(-x+c,-y),new(-x,-y+c),new(-x,y-c)};var st=new SurfaceTool();st.Begin(Mesh.PrimitiveType.Triangles);for(int i=0;i<8;i++){int j=(i+1)%8;Vector3 a=new(ring[i].X,ring[i].Y,z),b=new(ring[j].X,ring[j].Y,z),d=new(ring[i].X,ring[i].Y,-z),e=new(ring[j].X,ring[j].Y,-z);foreach(var p in new[]{a,e,b,a,d,e,new Vector3(0,0,z),a,b,new Vector3(0,0,-z),e,d})st.AddVertex(p);}st.GenerateNormals();return st.Commit();}
