 void ArtTree(Node3D root,float h,int seed){if((uint)seed%5==0){ArtPine(root,h,seed);return;}var random=new Random(seed);Tube(root,Vector3.Zero,new Vector3(.16f,h*.71f,-.1f),.32f,new Color(.29f,.23f,.17f),.1f).MaterialOverride=Textured(Wood,0,.8f);var body=new StaticBody3D();body.AddChild(new CollisionShape3D{Shape=new CylinderShape3D{Radius=.45f,Height=h*.65f},Position=new Vector3(0,h*.325f,0)});root.AddChild(body);for(int i=0;i<4;i++){float a=i*2.4f;Tube(root,new Vector3(0,h*.43f,0),new Vector3(Mathf.Sin(a)*h*.19f,h*(.62f+i*.06f),Mathf.Cos(a)*h*.18f),.12f,Wood,.025f);}var clusters=new MultiMesh{TransformFormat=MultiMesh.TransformFormatEnum.Transform3D,Mesh=new SphereMesh{Radius=1,Height=2,RadialSegments=14,Rings=7},UseColors=true,InstanceCount=13};for(int i=0;i<13;i++){float a=i*2.4f,rad=h*(.11f+(float)random.NextDouble()*.12f);var pos=new Vector3(Mathf.Sin(a)*rad,h*(.61f+(float)random.NextDouble()*.30f),Mathf.Cos(a)*rad);float size=h*(.13f+(float)random.NextDouble()*.07f);clusters.SetInstanceTransform(i,new Transform3D(Basis.Identity.Scaled(new Vector3(size*1.3f,size*.75f,size)),pos));clusters.SetInstanceColor(i,new Color(.75f+(float)random.NextDouble()*.25f,.75f+(float)random.NextDouble()*.25f,.65f,1));}root.AddChild(new MultiMeshInstance3D{Multimesh=clusters,MaterialOverride=WoodlandLeaves(),VisibilityRangeEnd=210});
 if(leafMesh==null){var st=new SurfaceTool();st.Begin(Mesh.PrimitiveType.Triangles);foreach(var v in new[]{new Vector3(-.14f,0,0),new Vector3(0,.04f,.10f),new Vector3(.14f,0,0),new Vector3(-.14f,0,0),new Vector3(.14f,0,0),new Vector3(0,-.025f,-.10f)})st.AddVertex(v);st.GenerateNormals();leafMesh=st.Commit();}var leaves=new MultiMesh{TransformFormat=MultiMesh.TransformFormatEnum.Transform3D,Mesh=leafMesh,InstanceCount=520};for(int i=0;i<520;i++){float a=(float)random.NextDouble()*Mathf.Tau,r=(float)random.NextDouble()*h*.33f;var cluster=clusters.GetInstanceTransform(i%13);float latitude=(float)random.NextDouble()*Mathf.Pi;Vector3 unit=new Vector3(Mathf.Sin(a)*Mathf.Sin(latitude),Mathf.Cos(latitude),Mathf.Cos(a)*Mathf.Sin(latitude));var pos=cluster.Origin+unit*cluster.Basis.Scale*1.02f;leaves.SetInstanceTransform(i,new Transform3D(Basis.FromEuler(new Vector3((float)random.NextDouble(),a,0)).Scaled(Vector3.One*(1+(float)random.NextDouble())),pos));}root.AddChild(new MultiMeshInstance3D{Multimesh=leaves,MaterialOverride=WoodlandLeaves(),CastShadow=GeometryInstance3D.ShadowCastingSetting.Off,VisibilityRangeEnd=120});}
