 void ArtBuilding(Node3D root,int x,int z,float size,float h,int tier){var pos=Ground(x,z);Box(root,pos+new Vector3(0,h/2,0),new Vector3(size,h,size),tier==3?new Color(.44f,.39f,.29f):new Color(.35f,.40f,.39f),true).MaterialOverride=Textured(tier==3?new Color(.55f,.45f,.30f):new Color(.48f,.48f,.42f),1,.35f);Box(root,pos+new Vector3(0,h+.15f,0),new Vector3(size+.5f,.3f,size+.5f),Ink);Box(root,pos+new Vector3(0,.35f,0),new Vector3(size+.2f,.7f,size+.2f),new Color(.25f,.28f,.26f));int floors=Math.Max(1,(int)(h/3.7f)),columns=(int)(size/3.0f);var mm=new MultiMesh{TransformFormat=MultiMesh.TransformFormatEnum.Transform3D,Mesh=new BoxMesh{Size=new Vector3(1.3f,1.65f,.08f)},InstanceCount=floors*columns*4};int index=0;for(int side=0;side<4;side++)for(int f=0;f<floors;f++)for(int w=0;w<columns;w++){float a=side*Mathf.Pi/2;var p=new Vector3((w-(columns-1)/2f)*2.7f,2.1f+f*3.7f,-size/2-.06f).Rotated(Vector3.Up,a);mm.SetInstanceTransform(index++,new Transform3D(Basis.FromEuler(new Vector3(0,a,0)),pos+p));}root.AddChild(new MultiMeshInstance3D{Multimesh=mm,MaterialOverride=Material(new Color(.12f,.21f,.25f))});for(int s=-1;s<=1;s+=2){Box(root,pos+new Vector3(s*(size/2-.1f),h/2,-size/2-.12f),new Vector3(.3f,h,.15f),new Color(.55f,.51f,.39f));}Box(root,pos+new Vector3(0,1.15f,-size/2-.12f),new Vector3(1.5f,2.3f,.18f),Wood);if(tier==3){Box(root,pos+new Vector3(0,3.5f,-size/2-.6f),new Vector3(size*.7f,.2f,1.4f),new Color(.39f,.29f,.19f));var sign=new Label3D{Text=new[]{"APOTHECARY","GENERAL STORE","ROOMS / VACANT","REPAIRS"}[(int)(game.World.Hash(x,z)%4)],Position=pos+new Vector3(0,3.0f,-size/2-.16f),FontSize=40,PixelSize=.012f,Modulate=new Color(.84f,.77f,.57f)};root.AddChild(sign);}}
