 void ArtWreck(Node3D node,bool burned){Color metal=burned?new Color(.13f,.14f,.13f):Rust;Bevel(node,new Vector3(0,.65f,0),new Vector3(2,.65f,4.2f),metal);Bevel(node,new Vector3(0,1.15f,.2f),new Vector3(1.8f,.8f,2),metal);Box(node,new Vector3(0,1.3f,-.84f),new Vector3(1.55f,.45f,.03f),new Color(.13f,.24f,.27f));for(int s=-1;s<=1;s+=2){for(int end=-1;end<=1;end+=2){Tube(node,new Vector3(s*.86f,.4f,end*1.35f),new Vector3(s*1.11f,.4f,end*1.35f),.35f,Ink);Tube(node,new Vector3(s*1.115f,.4f,end*1.35f),new Vector3(s*1.12f,.4f,end*1.35f),.16f,Steel);}Box(node,new Vector3(s*.91f,1.3f,.2f),new Vector3(.025f,.45f,1.65f),new Color(.14f,.22f,.24f));Box(node,new Vector3(s*.57f,.72f,-2.12f),new Vector3(.35f,.16f,.05f),new Color(.64f,.59f,.37f));}Box(node,new Vector3(0,.42f,-2.15f),new Vector3(1.75f,.14f,.10f),Steel);for(int i=-3;i<=3;i++)Box(node,new Vector3(i*.14f,.62f,-2.14f),new Vector3(.07f,.14f,.03f),Ink);}
